205	// startSessionPrefetch is the distill pipeline's producer: it prepares
206	// sessions in chronological order and dispatches their chunk agent calls into
207	// ONE shared pool, up to `concurrency` calls in flight ACROSS sessions — the
208	// per-session pool it replaces gave a 1-chunk session (the common case after
209	// stripping; the corpus median) no parallelism at all, serializing the run on
210	// agent latency.
211	//
212	// Two properties carry over from the per-session prefetcher and one is new:
213	//   - In-order delivery: the consumer applies chunks strictly in global
214	//     (session, chunk) order, so reconcile and fact application keep their
215	//     exact serial semantics; only agent round-trips overlap.
216	//   - Consumption-bounded lookahead: a pool slot is held from a call's launch
217	//     until its result is CONSUMED, so at most `concurrency` completed results
218	//     are ever buffered and an early abort stops dispatch within `concurrency`
219	//     calls of the last one consumed.
220	//   - Single dispatcher, global dispatch order: slots are acquired in exactly
221	//     the order the consumer will need results. Competing per-session
222	//     dispatchers over a shared pool could hand a freed slot to a session the
223	//     consumer is not ready for, buffering its result while the chunk the
224	//     consumer is blocked on starves — a deadlock at small pool sizes.
225	//
226	// The returned channel delivers sessions in order with lookahead
227	// distillSessionLookahead; it closes when all sessions are produced or ctx is
228	// canceled. Cancel ctx to stop preparation, dispatch, and in-flight calls.
229	func startSessionPrefetch(ctx context.Context, brainDir, repoDir string, args []string, sessions []exportSession, prevCache distillCache, distillOpts distillCommandOptions, resolveBranch func(exportSession) string) <-chan preparedSession {
230		prepared := make(chan preparedSession, distillSessionLookahead)
231		duplicateKeys := distillDuplicateSessionKeys(sessions, resolveBranch)
232		var sem chan struct{}
233		if distillOpts.concurrency > 1 {
234			sem = make(chan struct{}, distillOpts.concurrency)
235		}
236		// workSem bounds sessions HOLDING WORK — preprocessed chunk text awaiting
237		// or in agent calls — independently of the session buffer. The buffer must
238		// be deep so skip/cache streaks never starve dispatch (observed: a ~95%
239		// cache-hit region left a concurrency-8 pool running ONE call, because a
240		// 4-session lookahead held ~0.2 work-sessions); workSem keeps the memory
241		// for that depth bounded to a handful of sessions' chunk text. A slot is
242		// held from just before a session's transcript read (the chunks' memory is
243		// born there) until the consumer finishes its chunks.
244		workAhead := distillOpts.concurrency
245		if workAhead < 2 {
246			workAhead = 2
247		}
248		workSem := make(chan struct{}, workAhead)
249		// Stage A launches per-session PREP workers (transcript read,
250		// preprocessing, fingerprint/cache check, chunking) bounded by workSem and
251		// acquired in order; stage B awaits each session's future in order,
252		// delivers it, and dispatches its chunk calls. Prep parallelism matters as
253		// much as call parallelism on document-heavy corpora: preprocessing a
254		// multi-MB document costs seconds, and a serial prep stage was observed
255		// feeding only ~2 of 8 pool slots — the producer couldn't prepare sessions
256		// as fast as the pool retired their calls.
257		prepQueue := make(chan chan preparedSession, distillSessionLookahead)
258		go func() { // stage A: in-order prep launcher
259			defer close(prepQueue)
260			enqueue := func(f chan preparedSession) bool {
261				select {
262				case prepQueue <- f:
263					return true
264				case <-ctx.Done():
265					return false
266				}
267			}
268			for _, session := range sessions {
269				if ctx.Err() != nil {
270					return
271				}
272				ps := preparedSession{session: session, branch: resolveBranch(session)}
273				f := make(chan preparedSession, 1) // buffered: a worker outliving a canceled consumer delivers and exits
274				if (distillOpts.branch != "" && ps.branch != distillOpts.branch) ||
275					(distillOpts.session != "" && session.SessionID != distillOpts.session) {
276					ps.skip = true
277					f <- ps
278					if !enqueue(f) {
279						return
280					}
281					continue
282				}
283				if fingerprint, hit := cachedCheckpointDistill(prevCache, ps.session, ps.branch, duplicateKeys, distillOpts); hit {
284					ps.fingerprint, ps.cached = fingerprint, true
285					f <- ps
286					if !enqueue(f) {
287						return
288					}
289					continue
290				}
291				select {
292				case workSem <- struct{}{}:
293				case <-ctx.Done():
294					return
295				}
296				go func(ps preparedSession) {
297					releaseWork := func() { <-workSem }
298					data, readErr := readCanonicalHistoryTranscript(ctx, brainDir, ps.session.TranscriptPath)
299					if readErr != nil {
300						releaseWork()
301						ps.readErr = readErr
302						f <- ps
303						return
304					}
305					content := string(data)
306					// Strip tool calls/outputs and meta records up front: this is
307					// the actual input the agent distills. Fingerprinting the
308					// preprocessed input (not raw bytes) means churn confined to
309					// stripped tool I/O does not invalidate the cache.
310					distillInput := preprocessTranscriptForDistill(content)
311					ps.rawBytes = len(content)
312					ps.preBytes = len(distillInput)
313					ps.fingerprint = distillFingerprintForSession(ps.session, ps.branch, distillInput, distillOpts)
314					if !distillOpts.force {
315						cacheKey := distillSessionCacheKeyFor(ps.branch, ps.session, duplicateKeys)
316						if prev, ok := cachedDistillFingerprintForKey(prevCache, cacheKey); ok && (prev == ps.fingerprint || grandfatheredContentFingerprint(prev, ps.session, ps.branch, distillInput, distillOpts)) {
317							releaseWork()
318							ps.cached = true
319							f <- ps
320							return
321						}
322						// Pre-upgrade entry (legacy key + formula): the session is
323						// unchanged; the consumer rewrites it under the new
324						// key/format — lazy migration, zero agent calls. Skipped for
325						// a duplicated session id: the single legacy entry cannot
326						// say WHICH of the colliding exports produced it, and
327						// grandfathering both would mark a genuinely undistilled
328						// export as done. One re-distill, once, then both hold
329						// distinct keys.
330						if !duplicateKeys[distillSessionCacheKey(ps.branch, ps.session.SessionID)] &&
331							(!distillOpts.checkpointBacked || distillPreprocessingVersion == 1) && grandfatheredDistillFingerprint(prevCache, ps.session, ps.branch, distillInput) {
332							releaseWork()
333							ps.cached = true
334							f <- ps
335							return
336						}
337					}
338					ps.chunks = chunkTranscript(distillInput, distillOpts.maxChunkBytes)
339					ps.chunkHashes = distillChunkHashes(ps.chunks, distillOpts.cacheSalt)
340					if !distillOpts.force {
341						// Re-dispatch only chunks the cache has not seen succeed.
342						// Facts from skipped chunks are already in the store, and
343						// upsert-by-content-id makes even a stale skip harmless. A
344						// force run bypasses reuse: it just DROPPED the distilled
345						// facts it is about to regenerate.
346						if done := prevCache.chunkSet(distillSessionCacheKeyFor(ps.branch, ps.session, duplicateKeys)); len(done) > 0 {
347							kept := ps.chunks[:0]
348							for i := range ps.chunks {
349								if !done[ps.chunkHashes[i]] {
350									kept = append(kept, ps.chunks[i])
351								}
352							}
353							ps.chunks = kept
354						}
355					}
356					ps.release = releaseWork
357					f <- ps
358				}(ps)
359				if !enqueue(f) {
360					return
361				}
362			}
363		}()
364		go func() { // stage B: in-order delivery + global-order dispatch
365			defer close(prepared)
366			// distilled counts sessions this run actually dispatched agent calls
367			// for. The --max-sessions budget is enforced HERE, in the single
368			// in-order dispatcher, so the decision is deterministic (the same N
369			// sessions every time for a given order) and, crucially, no agent call
370			// is ever dispatched for a deferred session.
371			distilled := 0
372			for f := range prepQueue {
373				var ps preparedSession
374				select {
375				case ps = <-f:
376				case <-ctx.Done():
377					return
378				}
379				if ps.skip || ps.readErr != nil || ps.cached {
380					select {
381					case prepared <- ps:
382						continue
383					case <-ctx.Done():
384						return
385					}
386				}
387				if distillOpts.maxSessions > 0 && distilled >= distillOpts.maxSessions {
388					// Budget spent. Release the work slot the prep stage took (the
389					// consumer will never consume these chunks) and drop the chunk
390					// text so a deferred tail costs no memory.
391					if ps.release != nil {
392						ps.release()
393						ps.release = nil
394					}
395					ps.chunks = nil
396					ps.deferred = true
397					select {
398					case prepared <- ps:
399						continue
400					case <-ctx.Done():
401						return
402					}
403				}
404				distilled++
405				if sem == nil {
406					ps.seq = func(chunks []transcriptChunk) func(int) (string, error) {
407						return func(i int) (string, error) {
408							return distillOpts.run(ctx, repoDir, args, []byte(chunks[i].Text), distillOpts.timeout)
409						}
410					}(ps.chunks)
411					select {
412					case prepared <- ps:
413					case <-ctx.Done():
414						return
415					}
416					continue
417				}
418				ps.sem = sem
419				ps.results = make([]chan agentCallResult, len(ps.chunks))
420				for i := range ps.results {
421					ps.results[i] = make(chan agentCallResult, 1) // buffered: abandoned workers deliver and exit
422				}
423				// Deliver BEFORE dispatching: a session with more chunks than the
424				// pool must be consumable while its tail still dispatches.
425				select {
426				case prepared <- ps:
427				case <-ctx.Done():
428					return
429				}
430				for i := range ps.chunks {
431					if ctx.Err() != nil { // don't race a freed slot against cancellation
432						ps.results[i] <- agentCallResult{err: ctx.Err()}
433						continue
434					}
435					select {
436					case sem <- struct{}{}:
437					case <-ctx.Done():
438						ps.results[i] <- agentCallResult{err: ctx.Err()}
439						continue
440					}
441					go func(i int, chunks []transcriptChunk, results []chan agentCallResult) {
442						// A panic while processing one (untrusted) chunk must not crash the
443						// whole distill run and lose every other chunk's work; convert it to
444						// a per-chunk error so the slot is released and the run continues.
445						defer func() {
446							if r := recover(); r != nil {
447								results[i] <- agentCallResult{err: fmt.Errorf("distill worker panicked: %v", r), holdsSlot: true}
448							}
449						}()
450						out, err := distillOpts.run(ctx, repoDir, args, []byte(chunks[i].Text), distillOpts.timeout)
451						results[i] <- agentCallResult{out: out, err: err, holdsSlot: true}
452					}(i, ps.chunks, ps.results)
453				}
454			}
455		}()
456		return prepared
457	}
