// is never mistaken for "all of them".
func setupBackfillOfLabel(queued, pending int) string {
	if queued >= pending {
		return ""
	}
	return fmt.Sprintf(" (capped at %d of %d pending; --backfill-budget 0 for all)", queued, pending)
}

